/// <summary>
/// Show buttons when called from extension
/// </summary>
public void init()
{
    Object      getCaller;

    next init();

    getCaller = this.args().parmObject();

    if (getCaller is ISDIntgDMFFormBrowser)
    {
        this.design(0).controlName("ISDSelectAllCtrl").visible(true); 
        this.design(0).controlName("ISDDeselectAllCtrl").visible(true);
    }
}
